  unawaited(
    _runCopilotStream(
      events,
      model,
      context,
      options ?? const CopilotOptions(githubToken: ''),
      client,
    ),
  );
  return events;
}

Future<void> _runCopilotStream(
  AssistantMessageEventStream events,
  Model model,
  Context context,
  CopilotOptions options,
  http.Client? client,
) async {
  final state = ProviderStreamState(model);
