test('no injected client: the shared keep-alive client carries the stream', () async {
  // The shared client is stubbed through the providerHttpClientFactory
  // seam — the no-client fallback (sharedProviderHttpClient) is the one
  // `_runCopilotStream` line no other test reaches (CRAP ratchet: CC-12
  // at 97.1% reads 12.0035 > 12.0).
  final backend = FakeCopilotBackend()
    ..chatHandler = (_) async => sseResponse(chatSse());
  debugResetSharedProviderHttpClient();
  final previousFactory = providerHttpClientFactory;
  providerHttpClientFactory = () => backend.client();
  addTearDown(() {
    providerHttpClientFactory = previousFactory;
    debugResetSharedProviderHttpClient();
  });

  final events = await streamCopilot(
    copilotModel,
    simpleContext(),
    // PAT mode: the token manager answers from the token itself — the
    // only HTTP traffic in this test is the chat POST on the shared client.
    CopilotOptions(githubToken: 'github_pat_SHARED'),
  ).toList();

  expect(backend.chatCalls, 1);
  expect(backend.exchangeCalls, 0);
  final deltas = events.whereType<TextDeltaEvent>().toList();
  expect(deltas.map((d) => d.delta).join(), 'Hel lo');
});
